    id: "belarus-kalinkavichy-cities-v2", "sights": {"de": [{"name": "Lenin U.I.", "text": "Dieses Denkmal in Kalinkawitschy ist W.I. Lenin gewidmet.", "category": "historical", "coords": [29.331457, 52.128678]}, {"name": "Samalet MiG-15VTZ", "text": "Dieses Denkmal in Kalinkawitschy zeigt ein historisches Kampfflugzeug vom Typ MiG-15.", "category": "historical", "coords": [29.345311, 52.129776]}, {"name": "Dom dzitsyachai tvorchastsi", "text": "Dieses Kunstzentrum in Kalinkawitschy fördert die Kreativität von Kindern.", "category": "cultural", "coords": [29.335075, 52.121883]}, {"name": "Kalinkavitskaya dzitsyachaya shkola mastatstvau", "text": "Die Kinderkunstschule ist eine lokale Einrichtung für künstlerische Bildung in Kalinkawitschy.", "category": "cultural", "coords": [29.343142, 52.132517]}, {"name": "Paravoz Er-772", "text": "Dieses Denkmal in Kalinkawitschy besteht aus einer historischen Dampflokomotive der Baureihe Er-772.", "category": "historical", "coords": [29.314371, 52.138455]}, {"name": "Kastsel Naisvyatseishai Troitsy", "text": "Die Kirche der Heiligsten Dreifaltigkeit ist ein bedeutendes katholisches Gotteshaus in Kalinkawitschy.", "category": "religious", "coords": [29.339692, 52.132485]}], "hu": [{"name": "Lenin U.I.", "text": "Ez a kalinkavicsi emlékmű V.I. Leninnek állít emléket.", "category": "historical", "coords": [29.331457, 52.128678]}, {"name": "Samalet MiG-15VTZ", "text": "Ez a kalinkavicsi emlékmű egy történelmi MiG-15-ös repülőgépet ábrázol.", "category": "historical", "coords": [29.345311, 52.129776]}, {"name": "Dom dzitsyachai tvorchastsi", "text": "Ez a kalinkavicsi művészeti központ a gyermekek kreativitásának fejlesztését szolgálja.", "category": "cultural", "coords": [29.335075, 52.121883]}, {"name": "Kalinkavitskaya dzitsyachaya shkola mastatstvau", "text": "A kalinkavicsi gyermek művészeti iskola egy helyi művészeti oktatási intézmény.", "category": "cultural", "coords": [29.343142, 52.132517]}, {"name": "Paravoz Er-772", "text": "Ez a kalinkavicsi emlékmű egy történelmi Er-772-es gőzmozdonyból áll.", "category": "historical", "coords": [29.314371, 52.138455]}, {"name": "Kastsel Naisvyatseishai Troitsy", "text": "A Szentháromság-templom egy jelentős katolikus istentiszteleti hely Kalinkavicsiban.", "category": "religious", "coords": [29.339692, 52.132485]}], "ro": [{"name": "Lenin U.I.", "text": "Acest monument din Kalinkawitschy este dedicat lui V.I. Lenin.", "category": "historical", "coords": [29.331457, 52.128678]}, {"name": "Samalet MiG-15VTZ", "text": "Acest monument din Kalinkawitschy prezintă un avion istoric MiG-15.", "category": "historical", "coords": [29.345311, 52.129776]}, {"name": "Dom dzitsyachai tvorchastsi", "text": "Acest centru de arte din Kalinkawitschy încurajează creativitatea copiilor.", "category": "cultural", "coords": [29.335075, 52.121883]}, {"name": "Kalinkavitskaya dzitsyachaya shkola mastatstvau", "text": "Școala de arte pentru copii este o instituție locală de educație artistică din Kalinkawitschy.", "category": "cultural", "coords": [29.343142, 52.132517]}, {"name": "Paravoz Er-772", "text": "Acest monument din Kalinkawitschy constă într-o locomotivă istorică cu aburi Er-772.", "category": "historical", "coords": [29.314371, 52.138455]}, {"name": "Kastsel Naisvyatseishai Troitsy", "text": "Biserica Sfintei Treimi este un important lăcaș de cult catolic din Kalinkawitschy.", "category": "religious", "coords": [29.339692, 52.132485]}], "en": [{"name": "Lenin U.I.", "text": "This monument in Kalinkawitschy is dedicated to V.I. Lenin.", "category": "historical", "coords": [29.331457, 52.128678]}, {"name": "Samalet MiG-15VTZ", "text": "This monument in Kalinkawitschy features a historic MiG-15 aircraft.", "category": "historical", "coords": [29.345311, 52.129776]}, {"name": "Dom dzitsyachai tvorchastsi", "text": "This arts center in Kalinkawitschy fosters children's creativity.", "category": "cultural", "coords": [29.335075, 52.121883]}, {"name": "Kalinkavitskaya dzitsyachaya shkola mastatstvau", "text": "The Children's School of Arts is a local institution for artistic education in Kalinkawitschy.", "category": "cultural", "coords": [29.343142, 52.132517]}, {"name": "Paravoz Er-772", "text": "This monument in Kalinkawitschy consists of a historic Er-772 steam locomotive.", "category": "historical", "coords": [29.314371, 52.138455]}, {"name": "Kastsel Naisvyatseishai Troitsy", "text": "The Church of the Holy Trinity is a notable Catholic place of worship in Kalinkawitschy.", "category": "religious", "coords": [29.339692, 52.132485]}]},
