    id: "belarus-dzyarzhynsk-cities-v2", "sights": {"de": [{"name": "Burgruine und reformierte Kirchenruine", "text": "Diese archäologische Stätte in Dsjarschynsk umfasst die Ruinen einer ehemaligen Burg und einer calvinistischen Kirche.", "category": "historical", "coords": [27.127986, 53.690686]}, {"name": "Gistoryka-krayaznauchy muzei", "text": "Das Heimatmuseum in Dsjarschynsk widmet sich der Geschichte und Tradition der Region.", "category": "museum", "coords": [27.127529, 53.685222]}, {"name": "Gorodskaya stsena", "text": "Die städtische Bühne in Dsjarschynsk ist ein wichtiger Veranstaltungsort für lokale Aufführungen.", "category": "cultural", "coords": [27.127378, 53.683187]}, {"name": "Vystauka vaennykh autamabilyau", "text": "Dieses Museum in Dsjarschynsk zeigt eine faszinierende Ausstellung historischer Militärfahrzeuge.", "category": "museum", "coords": [27.119426, 53.673129]}, {"name": "DAK №23", "text": "Der Bunker Nr. 23 ist ein historisches militärisches Bauwerk und eine Sehenswürdigkeit in Dsjarschynsk.", "category": "landmark", "coords": [27.105524, 53.67648]}, {"name": "Kastsel Svyatoi Ganny", "text": "Die St.-Anna-Kirche ist ein sakrales Baudenkmal und eine bedeutende Attraktion in Dsjarschynsk.", "category": "landmark", "coords": [27.128397, 53.689433]}, {"name": "APK №046", "text": "Diese militärhistorische Verteidigungsanlage ist eine Attraktion in der Nähe von Dsjarschynsk.", "category": "landmark", "coords": [27.091344, 53.685668]}, {"name": "Zvanitsa", "text": "Dieser historische Glockenturm ist eine markante Sehenswürdigkeit in Dsjarschynsk.", "category": "landmark", "coords": [27.132616, 53.684527]}, {"name": "DAK №17", "text": "Der Bunker Nr. 17 ist ein Überbleibsel historischer Befestigungsanlagen und eine Attraktion in Dsjarschynsk.", "category": "landmark", "coords": [27.126609, 53.656741]}], "hu": [{"name": "Ruiny zamka i refarmatskai tsarkvy", "text": "Ez a dzsarzsinszki régészeti lelőhely egy egykori vár és egy kálvinista templom romjait foglalja magában.", "category": "historical", "coords": [27.127986, 53.690686]}, {"name": "Gistoryka-krayaznauchy muzei", "text": "A dzsarzsinszki helytörténeti múzeum a régió történelmének és hagyományainak szenteli magát.", "category": "museum", "coords": [27.127529, 53.685222]}, {"name": "Gorodskaya stsena", "text": "A dzsarzsinszki városi színpad a helyi előadások fontos helyszíne.", "category": "cultural", "coords": [27.127378, 53.683187]}, {"name": "Vystauka vaennykh autamabilyau", "text": "Ez a dzsarzsinszki múzeum történelmi katonai járművek lenyűgöző kiállítását mutatja be.", "category": "museum", "coords": [27.119426, 53.673129]}, {"name": "DAK №23", "text": "A 23-as bunker egy történelmi katonai építmény és látványosság Dzsarzsinszkben.", "category": "landmark", "coords": [27.105524, 53.67648]}, {"name": "Kastsel Svyatoi Ganny", "text": "A Szent Anna-templom egy egyházi műemlék és jelentős látványosság Dzsarzsinszkben.", "category": "landmark", "coords": [27.128397, 53.689433]}, {"name": "APK №046", "text": "Ez a hadtörténeti védelmi létesítmény egy látványosság Dzsarzsinszk közelében.", "category": "landmark", "coords": [27.091344, 53.685668]}, {"name": "Zvanitsa", "text": "Ez a történelmi harangtorony egy feltűnő látványosság Dzsarzsinszkben.", "category": "landmark", "coords": [27.132616, 53.684527]}, {"name": "DAK №17", "text": "A 17-es bunker a történelmi erődítmények maradványa és egy látványosság Dzsarzsinszkben.", "category": "landmark", "coords": [27.126609, 53.656741]}], "ro": [{"name": "Ruiny zamka i refarmatskai tsarkvy", "text": "Acest sit arheologic din Dsjarschynsk include ruinele unui fost castel și ale unei biserici calvine.", "category": "historical", "coords": [27.127986, 53.690686]}, {"name": "Gistoryka-krayaznauchy muzei", "text": "Muzeul de istorie locală din Dsjarschynsk este dedicat istoriei și tradiției regiunii.", "category": "museum", "coords": [27.127529, 53.685222]}, {"name": "Gorodskaya stsena", "text": "Scena orașului din Dsjarschynsk este un loc important pentru spectacole locale.", "category": "cultural", "coords": [27.127378, 53.683187]}, {"name": "Vystauka vaennykh autamabilyau", "text": "Acest muzeu din Dsjarschynsk prezintă o expoziție fascinantă de vehicule militare istorice.", "category": "museum", "coords": [27.119426, 53.673129]}, {"name": "DAK №23", "text": "Buncărul nr. 23 este o structură militară istorică și o atracție în Dsjarschynsk.", "category": "landmark", "coords": [27.105524, 53.67648]}, {"name": "Kastsel Svyatoi Ganny", "text": "Biserica Sfânta Ana este un monument sacru și o atracție importantă în Dsjarschynsk.", "category": "landmark", "coords": [27.128397, 53.689433]}, {"name": "APK №046", "text": "Această structură istorică militară de apărare este o atracție lângă Dsjarschynsk.", "category": "landmark", "coords": [27.091344, 53.685668]}, {"name": "Zvanitsa", "text": "Această clopotniță istorică este o atracție proeminentă în Dsjarschynsk.", "category": "landmark", "coords": [27.132616, 53.684527]}, {"name": "DAK №17", "text": "Buncărul nr. 17 este o rămășiță a fortificațiilor istorice și o atracție în Dsjarschynsk.", "category": "landmark", "coords": [27.126609, 53.656741]}], "en": [{"name": "Castle and Reformed Church ruins", "text": "This archaeological site in Dsjarschynsk features the ruins of a former castle and a Calvinist church.", "category": "historical", "coords": [27.127986, 53.690686]}, {"name": "Gistoryka-krayaznauchy muzei", "text": "The local history museum in Dsjarschynsk is dedicated to the history and traditions of the region.", "category": "museum", "coords": [27.127529, 53.685222]}, {"name": "Gorodskaya stsena", "text": "The city stage in Dsjarschynsk is an important venue for local performances.", "category": "cultural", "coords": [27.127378, 53.683187]}, {"name": "Vystauka vaennykh autamabilyau", "text": "This museum in Dsjarschynsk features a fascinating exhibition of historical military vehicles.", "category": "museum", "coords": [27.119426, 53.673129]}, {"name": "DAK №23", "text": "Pillbox No. 23 is a historical military structure and attraction in Dsjarschynsk.", "category": "landmark", "coords": [27.105524, 53.67648]}, {"name": "Kastsel Svyatoi Ganny", "text": "The Church of St. Anne is a religious monument and a notable attraction in Dsjarschynsk.", "category": "landmark", "coords": [27.128397, 53.689433]}, {"name": "APK №046", "text": "This military historical defense structure is an attraction near Dsjarschynsk.", "category": "landmark", "coords": [27.091344, 53.685668]}, {"name": "Zvanitsa", "text": "This historical bell tower is a prominent attraction in Dsjarschynsk.", "category": "landmark", "coords": [27.132616, 53.684527]}, {"name": "DAK №17", "text": "Pillbox No. 17 is a remnant of historical fortifications and an attraction in Dsjarschynsk.", "category": "landmark", "coords": [27.126609, 53.656741]}]},
