    id: "belarus-stolin-cities-v2", "sights": {"de": [{"name": "Stolinskii raionnyi kraevedcheskii muzei", "text": "Das Heimatmuseum des Bezirks Stolin beleuchtet die regionale Geschichte und Kultur von Stolin.", "category": "museum", "coords": [26.868242, 51.895969]}, {"name": "Vinakurnya", "text": "Dieses historische Brennereigebäude ist eine lokale Sehenswürdigkeit in der Stadt Stolin.", "category": "landmark", "coords": [26.875691, 51.893858]}, {"name": "Eshybot", "text": "Diese Stätte ist eine ehemalige Jeschiwa, die als historische Sehenswürdigkeit in Stolin erhalten ist.", "category": "landmark", "coords": [26.842022, 51.886507]}, {"name": "Stainya", "text": "Dieser historische Stall wird als bauliche Sehenswürdigkeit in der Stadt Stolin erhalten.", "category": "landmark", "coords": [26.870893, 51.898031]}, {"name": "Mestsa palatsa Radzivilau", "text": "Dieser Aussichtspunkt markiert die historische Stätte, an der einst der Radziwiłł-Palast in Stolin stand.", "category": "natural", "coords": [26.870558, 51.894529]}, {"name": "Pikhta Kavkazskaya", "text": "Diese Nordmannstanne ist eine natürliche Sehenswürdigkeit in der Stadt Stolin.", "category": "landmark", "coords": [26.874765, 51.896332]}, {"name": "Sinagoga", "text": "Diese Ruinen gehören zu einer historischen Synagoge in Stolin.", "category": "historical", "coords": [26.842946, 51.88651]}, {"name": "Tsarkva Ushestsya Gaspodnyaga (1938)", "text": "Die 1938 erbaute Himmelfahrtskirche ist eine historische religiöse Sehenswürdigkeit in Stolin.", "category": "landmark", "coords": [26.832322, 51.885444]}, {"name": "Tsentr dzitsyachai tvorchastsi", "text": "Dieses Kunstzentrum bietet Raum für kreative Aktivitäten von Kindern in Stolin.", "category": "cultural", "coords": [26.849993, 51.889727]}, {"name": "Vystavochnyi zal", "text": "Diese Ausstellungshalle ist eine Kunstgalerie, die verschiedene Werke in Stolin präsentiert.", "category": "museum", "coords": [26.861663, 51.894512]}], "hu": [{"name": "Stolinskii raionnyi kraevedcheskii muzei", "text": "A Stolin Járási Helytörténeti Múzeum Stolin regionális történelmét és kultúráját mutatja be.", "category": "museum", "coords": [26.868242, 51.895969]}, {"name": "Vinakurnya", "text": "Ez a történelmi lepárlóépület egy helyi látványosság Stolin városában.", "category": "landmark", "coords": [26.875691, 51.893858]}, {"name": "Eshybot", "text": "Ez a helyszín egy egykori jesiva, amelyet történelmi látványosságként őriztek meg Stolin városában.", "category": "landmark", "coords": [26.842022, 51.886507]}, {"name": "Stainya", "text": "Ezt a történelmi istállót építészeti látványosságként tartják fenn Stolin városában.", "category": "landmark", "coords": [26.870893, 51.898031]}, {"name": "Mestsa palatsa Radzivilau", "text": "Ez a kilátópont azt a történelmi helyszínt jelöli, ahol egykor a Radziwill-palota állt Stolin városában.", "category": "natural", "coords": [26.870558, 51.894529]}, {"name": "Pikhta Kavkazskaya", "text": "Ez a kaukázusi jegenyefenyő egy természeti látványosság Stolin városában.", "category": "landmark", "coords": [26.874765, 51.896332]}, {"name": "Sinagoga", "text": "Ezek a romok egy Stolin városában található történelmi zsinagógához tartoznak.", "category": "historical", "coords": [26.842946, 51.88651]}, {"name": "Tsarkva Ushestsya Gaspodnyaga (1938)", "text": "Az 1938-ban épült Mennybemenetel templom egy történelmi vallási látványosság Stolin városában.", "category": "landmark", "coords": [26.832322, 51.885444]}, {"name": "Tsentr dzitsyachai tvorchastsi", "text": "Ez a művészeti központ teret biztosít a gyermekek kreatív tevékenységeinek Stolin városában.", "category": "cultural", "coords": [26.849993, 51.889727]}, {"name": "Vystavochnyi zal", "text": "Ez a kiállítóterem egy művészeti galéria, amely különféle alkotásokat mutat be Stolin városában.", "category": "museum", "coords": [26.861663, 51.894512]}], "ro": [{"name": "Stolinskii raionnyi kraevedcheskii muzei", "text": "Muzeul de Istorie Locală a Districtului Stolin explorează istoria și cultura regională din Stolin.", "category": "museum", "coords": [26.868242, 51.895969]}, {"name": "Vinakurnya", "text": "Această clădire istorică a unei distilerii este o atracție locală în orașul Stolin.", "category": "landmark", "coords": [26.875691, 51.893858]}, {"name": "Eshybot", "text": "Acest sit este o fostă ieșiva, conservată ca atracție istorică în Stolin.", "category": "landmark", "coords": [26.842022, 51.886507]}, {"name": "Stainya", "text": "Acest grajd istoric este menținut ca o atracție structurală în orașul Stolin.", "category": "landmark", "coords": [26.870893, 51.898031]}, {"name": "Mestsa palatsa Radzivilau", "text": "Acest punct de belvedere marchează locul istoric unde se afla odată Palatul Radziwill în Stolin.", "category": "natural", "coords": [26.870558, 51.894529]}, {"name": "Pikhta Kavkazskaya", "text": "Acest brad caucazian este o atracție naturală situată în orașul Stolin.", "category": "landmark", "coords": [26.874765, 51.896332]}, {"name": "Sinagoga", "text": "Aceste ruine aparțin unei sinagogi istorice situate în Stolin.", "category": "historical", "coords": [26.842946, 51.88651]}, {"name": "Tsarkva Ushestsya Gaspodnyaga (1938)", "text": "Construită în 1938, Biserica Înălțării Domnului este o atracție religioasă istorică din Stolin.", "category": "landmark", "coords": [26.832322, 51.885444]}, {"name": "Tsentr dzitsyachai tvorchastsi", "text": "Acest centru de arte oferă un spațiu pentru activitățile creative ale copiilor din Stolin.", "category": "cultural", "coords": [26.849993, 51.889727]}, {"name": "Vystavochnyi zal", "text": "Această sală de expoziții este o galerie de artă care prezintă diverse lucrări în Stolin.", "category": "museum", "coords": [26.861663, 51.894512]}], "en": [{"name": "Stolinskii raionnyi kraevedcheskii muzei", "text": "The Stolin District Local Lore Museum explores the regional history and culture of Stolin.", "category": "museum", "coords": [26.868242, 51.895969]}, {"name": "Vinakurnya", "text": "This historic distillery building stands as a local attraction in the city of Stolin.", "category": "landmark", "coords": [26.875691, 51.893858]}, {"name": "Eshybot", "text": "This site is a former Yeshiva, preserved as a historical attraction in Stolin.", "category": "landmark", "coords": [26.842022, 51.886507]}, {"name": "Stainya", "text": "This historic stable is maintained as a structural attraction in the city of Stolin.", "category": "landmark", "coords": [26.870893, 51.898031]}, {"name": "Mestsa palatsa Radzivilau", "text": "This viewpoint marks the historical site where the Radziwill Palace once stood in Stolin.", "category": "natural", "coords": [26.870558, 51.894529]}, {"name": "Pikhta Kavkazskaya", "text": "This Caucasian Fir tree is a natural attraction located in the city of Stolin.", "category": "landmark", "coords": [26.874765, 51.896332]}, {"name": "Sinagoga", "text": "These ruins belong to a historical synagogue situated in Stolin.", "category": "historical", "coords": [26.842946, 51.88651]}, {"name": "Tsarkva Ushestsya Gaspodnyaga (1938)", "text": "Built in 1938, the Church of the Ascension is a historic religious attraction in Stolin.", "category": "landmark", "coords": [26.832322, 51.885444]}, {"name": "Tsentr dzitsyachai tvorchastsi", "text": "This arts center provides a space for children's creative activities in Stolin.", "category": "cultural", "coords": [26.849993, 51.889727]}, {"name": "Vystavochnyi zal", "text": "This exhibition hall is an art gallery showcasing various works in Stolin.", "category": "museum", "coords": [26.861663, 51.894512]}]},
